(()=>{
  'use strict';
  const root=document.getElementById('sevendays-refined-preview'),$=s=>root.querySelector(s),phone=$('.so-phone'),stage=$('.so-stage');
  const Kit=window.SevenThemeKit,Assets=window.SevenOrbitAssets,STEP=window.SevenOrbitRenderer.STEP;
  const apps=[
    {name:'哔哩哔哩',symbol:'bili',asset:'bilibili',color:'#ed6ba2',quota:90,remaining:1081},
    {name:'抖音',symbol:'♪',asset:'tiktok',color:'#17171f',quota:50,remaining:0},
    {name:'X',symbol:'X',asset:'x',color:'#17171b',quota:25,remaining:0},
    {name:'小红书',symbol:'红',asset:'xiaohongshu',color:'#ed3e55',quota:45,remaining:2663},
    {name:'淘宝',symbol:'淘',asset:'taobao',color:'#f47b25',quota:30,remaining:1720},
    {name:'京东',symbol:'京',asset:'jd',color:'#e64a52',quota:20,remaining:1200},
    {name:'拼多多',symbol:'拼',asset:'pinduoduo',color:'#db3e45',quota:30,remaining:1800}
  ];
  const KEY='sevendays.orbit.appearance.v1',dark=matchMedia('(prefers-color-scheme:dark)'),reduced=matchMedia('(prefers-reduced-motion:reduce)');
  let themeId='saturn',themeStored=false,colors={},engine,angle=0,velocity=0,selected=0,tween=null,pointer=null,frame=0,lastFrame=0,wheelTimer=0,toastTimer=0,inViewport=true,restoreFocus=null,assetsReady=false;
  const iconModels=new Map(),clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),period=()=>apps.length*STEP;
  const wrap=a=>((a+period()/2)%period()+period())%period()-period()/2;
  const nearest=()=>((Math.round(-angle/STEP)%apps.length)+apps.length)%apps.length;
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const time=s=>s<=0?'已到限':`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
  const appTime=a=>a.quota===0?'全天禁用':time(a.remaining);
  try{const value=localStorage.getItem(KEY);if(Object.hasOwn(Kit.appearances,value)){themeId=value;themeStored=true;}}catch(error){}
  function readColors(){const cs=getComputedStyle(root),probe=document.createElement('span');probe.style.display='none';root.append(probe);for(const [key,variable]of Object.entries({surface:'--so-surface',ink:'--so-ink',muted:'--so-muted',soft:'--so-soft',primary:'--so-primary'})){probe.style.color=cs.getPropertyValue(variable).trim();colors[key]=getComputedStyle(probe).color;}probe.remove();}
  function icon(a){const key=a.asset||a.name;iconModels.set(key,a);return `<canvas class="so-app-icon" width="96" height="96" data-icon="${escape(key)}" aria-hidden="true"></canvas>`;}
  function paintIcons(){if(!$('.so-modal').hidden)root.querySelectorAll('canvas[data-icon]').forEach(c=>{const a=iconModels.get(c.dataset.icon);if(a)Assets.draw(c.getContext('2d'),a,0,0,96);});Assets.draw($('.so-current-icon').getContext('2d'),apps[selected],0,0,96);}
  const gestureGain=()=>Math.min(1,apps.length/7);
  function moving(){return !!tween||!!pointer?.dragged||Math.abs(velocity)>.025;}
  function motionLabel(){$('.so-motion-label').textContent=moving()?'旋转中':'已停稳';$('.so-brake').textContent=moving()?'Ⅱ':'▷';$('.so-brake').setAttribute('aria-label',moving()?'立即停止旋转':'转动卡片');}
  function updateSelection(force=false){const index=nearest();if(index===selected&&!force)return;selected=index;const a=apps[selected],used=Math.max(0,a.quota*60-a.remaining),fraction=a.quota?clamp(a.remaining/(a.quota*60),0,1):0;$('.so-count').textContent=`${selected+1} / ${apps.length}`;const total=apps.reduce((sum,item)=>sum+Math.max(0,item.quota*60-item.remaining),0),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60);$('.so-summary strong').innerHTML=(hours?hours+'<span>小时</span>':'')+minutes+'<span>'+ (hours?'分':'分钟')+'</span>';$('.so-selection-name').textContent=a.name;$('.so-selection-quota').textContent=a.quota===0?'全天禁用':`每天 ${a.quota} 分钟`;$('.so-selection-time').textContent=appTime(a);$('.so-selection-time').classList.toggle('so-exhausted',!a.remaining);$('.so-remaining-label').textContent=a.quota===0?'规则':a.remaining?'剩余时间':'今日额度';$('.so-remaining-fill').style.width=fraction*100+'%';$('.so-used-label').textContent=`已用 ${Math.floor(used/60)} 分钟`;$('.so-selected').setAttribute('aria-label',`${a.name}，${a.quota===0?'全天禁用':a.remaining===0?'今日已到限':'剩余 '+time(a.remaining)}，查看规则`);for(const s of ['.so-prev','.so-next','.so-brake'])$(s).disabled=apps.length<2;stage.style.touchAction=apps.length<2?'pan-y':'none';paintIcons();}
  function announce(){$('.so-sr').textContent=`已选 ${apps[selected].name}，${appTime(apps[selected])}`;}
  function draw(){if(engine){engine.render(angle,selected);root.dataset.renderer=engine.kind;}}
  function freeze(){if(pointer){try{stage.releasePointerCapture(pointer.id);}catch(error){}}pointer=null;velocity=0;tween=null;clearTimeout(wheelTimer);if(frame)cancelAnimationFrame(frame);frame=0;lastFrame=0;updateSelection();motionLabel();draw();announce();}
  function wake(){if(!frame&&inViewport&&!document.hidden&&$('.so-modal').hidden){lastFrame=performance.now();frame=requestAnimationFrame(tick);}}
  function tick(now){frame=0;const dt=clamp((now-lastFrame)/1000,0,.04);lastFrame=now;if(tween){const p=clamp((now-tween.start)/tween.duration,0,1),ease=1-Math.pow(1-p,3);angle=wrap(tween.from+tween.delta*ease);if(p===1){const done=tween.done;tween=null;velocity=0;updateSelection();motionLabel();draw();announce();if(done)done();return;}}else if(!pointer&&Math.abs(velocity)>.025){angle=wrap(angle+velocity*dt);velocity*=Math.exp(-1.2*dt);if(Math.abs(velocity)<.07){velocity=0;focusApp(nearest());return;}}updateSelection();motionLabel();draw();if(moving())frame=requestAnimationFrame(tick);}
  function focusApp(index,done){index=((index%apps.length)+apps.length)%apps.length;velocity=0;const target=-index*STEP,delta=wrap(target-angle);if(reduced.matches||!inViewport||document.hidden||Math.abs(delta)<.002){angle=wrap(target);tween=null;updateSelection(true);motionLabel();draw();announce();if(done)done();return;}tween={from:angle,delta,start:performance.now(),duration:clamp(260+Math.abs(delta)*32,260,580),done};wake();}
  function syncTheme(){root.dataset.appearance=themeId;const a=Kit.appearances[themeId];$('.so-theme-name').textContent=a.name;$('.so-theme').setAttribute('aria-label','选择外观主题，当前'+a.name);}
  function setAppearance(id,{persist=true,announce:voice=true}={}){if(!Object.hasOwn(Kit.appearances,id))return false;freeze();themeId=id;syncTheme();readColors();if(persist){try{localStorage.setItem(KEY,id);themeStored=true;}catch(error){themeStored=false;}}engine.setTheme(id);updateSelection(true);draw();if(voice)$('.so-sr').textContent='外观主题：'+Kit.appearances[id].name;return true;}
  function showModal(title,html,setup){sheetMotion.reset();freeze();restoreFocus=document.activeElement;$('#so-sheet-title').textContent=title;$('.so-sheet-content').innerHTML=html;$('.so-modal').hidden=false;for(const child of phone.children)if(!child.classList.contains('so-modal')&&!child.classList.contains('so-toast')&&!child.classList.contains('so-sr'))child.inert=true;$('.so-sheet-content').scrollTop=0;if(setup)setup($('.so-sheet-content'));paintIcons();$('.so-close').focus({preventScroll:true});}
  function closeModal(animate=false){if(animate===true&&!$('.so-modal').hidden){sheetMotion.dismiss();return;}sheetMotion.reset();$('.so-modal').hidden=true;$('.so-sheet-content').replaceChildren();for(const child of phone.children)child.inert=false;if(restoreFocus?.isConnected)restoreFocus.focus({preventScroll:true});restoreFocus=null;draw();}
  function showThemeChooser(){if(!$('.so-modal').hidden)closeModal();showModal('外观主题',Object.entries(Kit.appearances).map(([id,a])=>`<button class="so-theme-choice" type="button" data-appearance-choice="${id}" aria-pressed="${id===themeId}"><canvas width="200" height="128" aria-hidden="true"></canvas><span><strong>${a.name}</strong><small>${a.description}</small></span><b aria-hidden="true">${id===themeId?'✓':''}</b></button>`).join(''),body=>body.querySelectorAll('[data-appearance-choice]').forEach(b=>{const id=b.dataset.appearanceChoice;Kit.thumbnail(b.querySelector('canvas'),id,dark.matches);b.addEventListener('click',()=>{setAppearance(id);closeModal();});}));}
  function showDetails(i){const a=apps[i],used=Math.max(0,a.quota*60-a.remaining);showModal(a.name,`<div class="so-detail-hero"><span>${a.quota===0?'规则':a.remaining===0?'今日额度':'剩余时间'}</span><strong>${appTime(a)}</strong></div><div class="so-detail-line"><span>每日额度</span><span>${a.quota===0?'全天禁用':a.quota+' 分钟'}</span></div><div class="so-detail-line"><span>今日已用</span><span>${Math.floor(used/60)} 分 ${used%60} 秒</span></div><div class="so-detail-line"><span>额度恢复</span><span>${a.quota===0?'不自动恢复':'明天 00:00'}</span></div><div class="so-detail-line"><span>规则可调整</span><span>11月6日 21:30</span></div>`);}
  const sheetMotion=window.SevenSheetMotion.bind({sheet:$('.so-sheet'),chrome:$('.so-sheet-chrome'),scrim:$('.so-scrim'),isReduced:()=>reduced.matches,onDismiss:()=>closeModal(false)});
  $('.so-close').addEventListener('click',()=>closeModal(true));$('.so-scrim').addEventListener('click',()=>closeModal(true));
  $('.so-theme').addEventListener('click',showThemeChooser);
  $('.so-prev').addEventListener('click',()=>{freeze();focusApp(selected-1);});$('.so-next').addEventListener('click',()=>{freeze();focusApp(selected+1);});
  $('.so-brake').addEventListener('click',()=>{if(moving()){freeze();return;}if(reduced.matches){focusApp(selected+1);return;}velocity=1.5*gestureGain();motionLabel();wake();});
  $('.so-selected').addEventListener('click',()=>{freeze();showDetails(selected);});
  $('.so-index').addEventListener('click',()=>showModal('选择应用',apps.map((a,i)=>`<button class="so-app-choice" type="button" data-select="${i}">${icon(a)}<strong>${escape(a.name)}</strong><span>${appTime(a)}</span></button>`).join(''),body=>body.querySelectorAll('[data-select]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.select);closeModal();focusApp(i);}))))
  $('.so-settings').addEventListener('click',()=>showModal('设备与权限',`<div><div class="so-device-title">iQOO 15</div><div class="so-device-sub">Android 16 · V2505A</div></div><button class="so-setting so-setting-theme" type="button"><span>外观主题</span><span>${Kit.appearances[themeId].name} ›</span></button><div class="so-setting"><span>无障碍服务</span><span>已连接</span></div><div class="so-setting"><span>持续保护通知</span><span>已运行</span></div><div class="so-setting"><span>最近任务卡片</span><span>隐藏</span></div><div class="so-setting"><span>额度即将用完提醒</span><span>未启用</span></div><div class="so-setting"><span>系统电池优化</span><span>查看设置</span></div><div class="so-setting"><span>iQOO / vivo 后台设置</span><span>查看设置</span></div><div class="so-setting"><span>运行诊断</span><span>服务事件与退出记录</span></div>`,body=>body.querySelector('.so-setting-theme').addEventListener('click',showThemeChooser)));
  const candidates=[{name:'微博',symbol:'微',color:'#e56844'},{name:'YouTube',symbol:'▶',color:'#dc4146'},{name:'Telegram',symbol:'↗',color:'#3996c6'}];
  $('.so-add').addEventListener('click',()=>{const available=candidates.filter(a=>!apps.some(b=>a.name===b.name));if(!available.length){toast('预览应用已全部加入');return;}const chosen=new Set();showModal('添加应用',available.map((a,i)=>`<button class="so-app-choice" type="button" aria-pressed="false" data-candidate="${i}">${icon(a)}<strong>${escape(a.name)}</strong><span>＋</span></button>`).join('')+`<label class="so-number">每天可用分钟数<input class="so-minutes" type="number" min="0" max="1440" step="1" value="30" inputmode="numeric" aria-label="每天可用分钟数"></label><label class="so-consent"><input type="checkbox"><span>保存后锁定七天，期间不能修改或删除</span></label><button class="so-primary so-confirm-add" type="button" disabled>加入轨道</button>`,body=>{const input=body.querySelector('.so-minutes'),consent=body.querySelector('input[type=checkbox]'),save=body.querySelector('.so-confirm-add'),gate=()=>save.disabled=!chosen.size||!consent.checked||input.value===''||!Number.isInteger(Number(input.value))||Number(input.value)<0||Number(input.value)>1440;body.querySelectorAll('[data-candidate]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.candidate);chosen.has(i)?chosen.delete(i):chosen.add(i);b.setAttribute('aria-pressed',String(chosen.has(i)));consent.checked=false;gate();}));input.addEventListener('input',()=>{consent.checked=false;gate();});consent.addEventListener('change',gate);save.addEventListener('click',()=>{if(save.disabled)return;const first=apps.length,n=Number(input.value);for(const i of chosen)apps.push({...available[i],quota:n,remaining:n*60});closeModal();angle=wrap(-first*STEP);updateSelection(true);draw();announce();toast('已加入预览轨道');});});});
  function toast(text){clearTimeout(toastTimer);$('.so-toast').textContent=text;$('.so-toast').hidden=false;toastTimer=setTimeout(()=>$('.so-toast').hidden=true,1400);}
  stage.addEventListener('pointerdown',e=>{if(e.button>0||pointer)return;const wasMoving=moving();freeze();pointer={id:e.pointerId,x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,lastTime:performance.now(),wasMoving,dragged:false,axis:null,samples:[]};stage.setPointerCapture(e.pointerId);});
  stage.addEventListener('pointermove',e=>{if(!pointer||e.pointerId!==pointer.id)return;const p=pointer,dx=e.clientX-p.x,dy=e.clientY-p.y;if(!p.dragged&&Math.hypot(dx,dy)>5){p.dragged=true;p.axis=Math.abs(dy)>Math.abs(dx)*1.25?'y':'x';}if(!p.dragged||apps.length<2)return;const now=performance.now(),delta=(p.axis==='y'?-(e.clientY-p.lastY)*.012:(e.clientX-p.lastX)*.012)*gestureGain();angle=wrap(angle+delta);p.samples.push({d:delta,t:now});p.samples=p.samples.filter(s=>now-s.t<110);p.lastX=e.clientX;p.lastY=e.clientY;p.lastTime=now;updateSelection();motionLabel();draw();});
  function endPointer(e,cancelled){if(!pointer||pointer.id!==e.pointerId)return;const p=pointer;pointer=null;try{stage.releasePointerCapture(e.pointerId);}catch(error){}if(cancelled){freeze();return;}if(p.dragged){if(apps.length<2){freeze();return;}if(reduced.matches){focusApp(nearest());return;}const now=performance.now(),samples=p.samples.filter(s=>now-s.t<110),elapsed=samples.length>1?(samples.at(-1).t-samples[0].t)/1000:.07;velocity=samples.length?clamp(samples.reduce((v,s)=>v+s.d,0)/Math.max(.04,elapsed),-6.5*gestureGain(),6.5*gestureGain()):0;if(now-p.lastTime>140)velocity=0;if(Math.abs(velocity)>.15){motionLabel();wake();}else focusApp(nearest());return;}if(p.wasMoving){freeze();return;}const index=engine.hit(e.clientX,e.clientY);if(index===null){freeze();return;}if(index===selected)focusApp(index,()=>showDetails(index));else focusApp(index);}
  stage.addEventListener('pointerup',e=>endPointer(e,false));stage.addEventListener('pointercancel',e=>endPointer(e,true));
  stage.addEventListener('wheel',e=>{if(!$('.so-modal').hidden||apps.length<2)return;e.preventDefault();freeze();const delta=clamp(Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY,-200,200);angle=wrap(angle+delta*.008*gestureGain());updateSelection();draw();clearTimeout(wheelTimer);wheelTimer=setTimeout(()=>{if(reduced.matches)focusApp(nearest());else{velocity=clamp(delta*.025,-3,3)*gestureGain();motionLabel();wake();}},90);},{passive:false});
  root.addEventListener('keydown',e=>{if(!$('.so-modal').hidden){if(e.key==='Escape'){e.preventDefault();closeModal(true);}if(e.key==='Tab'){const list=[...$('.so-sheet').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')],first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(e.target instanceof HTMLInputElement)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();freeze();focusApp(selected+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1));}});
  syncTheme();readColors();engine=new window.SevenOrbitRenderer.Renderer($('.so-webgl'),$('.so-fallback-cards'),{apps:()=>apps,colors:()=>colors,dark:()=>dark.matches,drawIcon:Assets.draw,theme:themeId,onSelect:index=>{freeze();if(index===selected)focusApp(index,()=>showDetails(index));else focusApp(index);}});if(engine.theme!==themeId)engine.setTheme(themeId);root.dataset.renderer=engine.kind;updateSelection(true);motionLabel();draw();
  new ResizeObserver(()=>{engine.resize();draw();}).observe(stage);
  if(window.IntersectionObserver)new IntersectionObserver(entries=>{inViewport=entries[0].isIntersecting;if(!inViewport)freeze();else draw();},{threshold:.01}).observe(root);
  document.addEventListener('visibilitychange',()=>{if(document.hidden){freeze();if(sheetMotion.closing)closeModal(false);else sheetMotion.reset();}else draw();});
  dark.addEventListener('change',()=>{readColors();engine.setTheme(themeId);root.querySelectorAll('[data-appearance-choice]').forEach(b=>Kit.thumbnail(b.querySelector('canvas'),b.dataset.appearanceChoice,dark.matches));draw();});reduced.addEventListener('change',()=>{freeze();focusApp(nearest());});
  $('.so-webgl').addEventListener('webglcontextlost',e=>{e.preventDefault();freeze();engine.forceFallback();root.dataset.renderer=engine.kind;draw();});
  Assets.ready.then(()=>{assetsReady=true;engine.clearTextures();paintIcons();draw();});
  root.sevenOrbit={getState:()=>({angle,velocity,selected,name:apps[selected].name,count:apps.length,moving:moving(),theme:themeId,themeStored,planetRadius:Kit.appearances[themeId].radius,ringKind:Kit.appearances[themeId].kind,modal:!$('.so-modal').hidden,assetsReady,inViewport,pageVisible:!document.hidden,...engine.stats()}),focusApp,freeze,showDetails,apps,setAppearance,geometrySnapshot:()=>engine.inspectGeometry(),geometryAt:a=>engine.geometryAt(a),forceFallback:()=>{freeze();engine.forceFallback();root.dataset.renderer=engine.kind;draw();}};
})();
